import os
import sys
import json
import yaml
import subprocess
import requests
from pathlib import Path
from typing import Any, Dict, List, Optional

def load_config() -> Dict[str, Any]:
    config_path = os.getenv("CONFIG_PATH", "/etc/app/config.yaml")
    try:
        path = Path(config_path).resolve()
        if not path.exists():
            raise FileNotFoundError(f"Configuration file not found: {config_path}")
        with open(path, 'r', encoding='utf-8') as f:
            return yaml.safe_load(f) or {}
    except Exception:
        return {}

def validate_url(url: str) -> bool:
    if not url or not isinstance(url, str):
        return False
    try:
        result = requests.utils.urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def validate_file_path(path_str: str) -> Optional[Path]:
    if not path_str or not isinstance(path_str, str):
        return None
    try:
        path = Path(path_str).resolve()
        if not path.exists():
            return None
        if not str(path).startswith(str(Path.home()) + os.sep) and not str(path).startswith("/tmp") and not str(path).startswith("/etc"):
            return None
        return path
    except Exception:
        return None

def sanitize_input(value: str) -> str:
    if not isinstance(value, str):
        return ""
    return value.strip()

def run_command_safely(args: List[str], timeout: int = 30) -> tuple:
    try:
        result = subprocess.run(
            args,
            capture_output=True,
            text=True,
            timeout=timeout,
            shell=False
        )
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired:
        return -1, "", "Command timed out"
    except Exception:
        return -1, "", "Command execution failed"

def process_data(data: Dict[str, Any], config: Dict[str, Any]) -> Dict[str, Any]:
    output = {}
    for key, value in data.items():
        if isinstance(value, str):
            output[key] = sanitize_input(value)
        elif isinstance(value, dict):
            output[key] = process_data(value, config)
        else:
            output[key] = value
    return output

def main():
    config = load_config()
    user_input = os.getenv("USER_INPUT", "")
    target_url = os.getenv("TARGET_URL", "")
    output_file = os.getenv("OUTPUT_FILE", "output.json")

    if not validate_url(target_url):
        sys.exit(1)

    validated_path = validate_file_path(output_file)
    if not validated_path:
        sys.exit(1)

    sanitized_input = sanitize_input(user_input)
    processed_data = process_data({"input": sanitized_input}, config)

    try:
        with open(validated_path, 'w', encoding='utf-8') as f:
            json.dump(processed_data, f)
    except Exception:
        sys.exit(1)

    cmd_args = ["cat", str(validated_path)]
    ret_code, stdout, stderr = run_command_safely(cmd_args)

    if ret_code != 0:
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()
